import re


def title_of(html: str) -> str:
    """Return the text between the first <title> and </title> tags in html.

    Tag matching is case-insensitive and <title> may carry attributes.
    The text is returned exactly as it appears, without stripping whitespace.
    Returns an empty string when there is no complete title element.
    The input is already-fetched HTML; this function performs no I/O.
    """
    open_tag = re.search(r"<title(?:\s[^>]*)?>", html, re.IGNORECASE)
    if open_tag is None:
        return ""
    close_tag = re.compile(r"</title\s*>", re.IGNORECASE).search(html, open_tag.end())
    if close_tag is None:
        return ""
    return html[open_tag.end() : close_tag.start()]


def test_title_of_simple() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_title_of_case_insensitive() -> None:
    assert title_of("<HTML><TITLE>Shout</TITLE></HTML>") == "Shout"


def test_title_of_with_attributes() -> None:
    assert title_of('<title lang="en">Doc</title>') == "Doc"


def test_title_of_missing_returns_empty() -> None:
    assert title_of("<html><body>no title here</body></html>") == ""


def test_title_of_unclosed_returns_empty() -> None:
    assert title_of("<title>never closed") == ""


def test_title_of_empty_input() -> None:
    assert title_of("") == ""


def test_title_of_preserves_whitespace() -> None:
    assert title_of("<title>  padded  </title>") == "  padded  "


def test_title_of_uses_first_title() -> None:
    assert title_of("<title>one</title><title>two</title>") == "one"
